// This component provides a form for hospital staff to submit new blood requests.
import React, { useState } from 'react';
import axios from 'axios';
import './SubmitRequestForm.css';

const API_URL = 'http://localhost:3001';

const SubmitRequestForm = () => {
    const [patientName, setPatientName] = useState('');
    const [patientBloodType, setPatientBloodType] = useState('A+');
    const [urgency, setUrgency] = useState('Scheduled');
    const [componentType, setComponentType] = useState('Whole Blood');
    const [quantity, setQuantity] = useState(1);
    const [notes, setNotes] = useState('');
    
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setSuccess(null);

        if (!patientName.trim() || quantity < 1) {
            setError('Patient name and a valid quantity are required.');
            return;
        }

        const requestData = {
            hospitalId: 1, 
            staffId: 101,
            patientName,
            patientBloodType,
            urgency,
            items: [{ componentType, quantity, notes }]
        };

        try {
            const response = await axios.post(`${API_URL}/requests`, requestData);
            setSuccess(`Request submitted successfully! Request ID: ${response.data.requestId}`);
            // Reset form
            setPatientName('');
            setPatientBloodType('A+');
            setUrgency('Scheduled');
            setComponentType('Whole Blood');
            setQuantity(1);
            setNotes('');
        } catch (err) {
            setError('Failed to submit request. Please check the backend server.');
            console.error(err);
        }
    };

    return (
        <div className="form-container">
            <h2>Submit New Blood Request</h2>
            <form onSubmit={handleSubmit} className="request-form">
                {error && <div className="alert error">{error}</div>}
                {success && <div className="alert success">{success}</div>}

                <div className="form-group">
                    <label>Patient Full Name</label>
                    <input
                        type="text"
                        value={patientName}
                        onChange={(e) => setPatientName(e.target.value)}
                        placeholder="e.g., John Doe"
                        required
                    />
                </div>

                <div className="form-group">
                    <label>Patient Blood Type</label>
                    <select value={patientBloodType} onChange={(e) => setPatientBloodType(e.target.value)}>
                        <option value="A+">A+</option>
                        <option value="A-">A-</option>
                        <option value="B+">B+</option>
                        <option value="B-">B-</option>
                        <option value="AB+">AB+</option>
                        <option value="AB-">AB-</option>
                        <option value="O+">O+</option>
                        <option value="O-">O-</option>
                    </select>
                </div>

                <div className="form-group">
                    <label>Urgency</label>
                    <select value={urgency} onChange={(e) => setUrgency(e.target.value)}>
                        <option value="Scheduled">Scheduled</option>
                        <option value="Urgent">Urgent</option>
                        <option value="Emergency">Emergency</option>
                    </select>
                </div>

                <fieldset>
                    <legend>Request Details</legend>
                    <div className="form-group">
                        <label>Blood Component</label>
                        <input
                            type="text"
                            value={componentType}
                            onChange={(e) => setComponentType(e.target.value)}
                            placeholder="e.g., Whole Blood, Platelets"
                        />
                    </div>
                    <div className="form-group">
                        <label>Quantity (units)</label>
                        <input
                            type="number"
                            value={quantity}
                            onChange={(e) => setQuantity(parseInt(e.target.value, 10))}
                            min="1"
                        />
                    </div>
                    <div className="form-group">
                        <label>Notes / Special Requirements</label>
                        <textarea
                            value={notes}
                            onChange={(e) => setNotes(e.target.value)}
                            placeholder="e.g., CMV-Negative, Irradiated"
                        />
                    </div>
                </fieldset>

                <button type="submit" className="submit-btn">Submit Request</button>
            </form>
        </div>
    );
};

export default SubmitRequestForm;
